mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("values=[10,20,30,40]; choices=[0,1,1,3]","40"),
        ("values=[5,6,7]; choices=[0,0,2]","7"),
        ("values=[9]; choices=[0]","9"),
        ("values=[1,2,3,4]; choices=[0,0,0,0]","1"),
        ("values=[8,7,6]; choices=[0,1,0]","7"),
        ("  \nvalues=[10,20,30,40]; choices=[0,1,1,3]\n  ","40"),
        ("\nvalues=[8,7,6]; choices=[0,1,0]\n","7")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS reservoir-sampling");
}
